import sys

def solve():
    input = sys.stdin.readline
    N, M, A, B = map(int, input().split())

    bad = []
    for _ in range(M):
        L, R = map(int, input().split())
        bad.append((L, R))

    intervals = []
    cur = 1
    for L, R in bad:
        if cur <= L - 1:
            intervals.append((cur, L - 1, True))
        intervals.append((L, R, False))
        cur = R + 1
    if cur <= N:
        intervals.append((cur, N, True))

    mask = (1 << B) - 1
    jump_mask = 0
    for d in range(A, B + 1):
        jump_mask |= 1 << (d - 1)

    state = 1  # bit k: current_position - k is reachable
    pos = 1

    for l, r, is_good in intervals:
        if pos < l:
            shift = l - pos
            state = (state << shift) & mask if shift < B else 0
            pos = l

        length = r - l + 1

        if not is_good:
            state = (state << length) & mask if length < B else 0
            pos = r
            if state == 0 and pos < N:
                print("No")
                return
            continue

        steps = r - pos
        seen = {}
        t = 0
        while t < steps:
            if state == 0:
                print("No")
                return
            if state in seen:
                cycle = t - seen[state]
                rem = steps - t
                t += (rem // cycle) * cycle
                if t >= steps:
                    break
            else:
                seen[state] = t

            new_bit = 1 if (state & jump_mask) else 0
            state = ((state << 1) | new_bit) & mask
            t += 1

        pos = r

    print("Yes" if (state & 1) else "No")

if __name__ == "__main__":
    solve()
